let database;
function db(){if(!database)database=new Promise((resolve,reject)=>{if(!globalThis.indexedDB)return reject(Error('Device photo storage is unavailable.'));const request=indexedDB.open('toolnest-media',1);request.onupgradeneeded=()=>request.result.createObjectStore('foam-photos');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});return database;}
export async function storePhoto(id,blob){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('foam-photos','readwrite');tx.objectStore('foam-photos').put(blob,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Photo storage interrupted.'));});}
export async function loadPhoto(id){const database=await db();return new Promise((resolve,reject)=>{const request=database.transaction('foam-photos').objectStore('foam-photos').get(id);request.onsuccess=()=>resolve(request.result||null);request.onerror=()=>reject(request.error);});}
export function blobDataURL(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});}
export function dataURLBlob(url){const [header,payload]=url.split(','),bytes=Uint8Array.from(atob(payload),c=>c.charCodeAt(0));return new Blob([bytes],{type:header.includes('image/png')?'image/png':'image/jpeg'});}
